#pragma once
#include <algorithm>
#include <cmath>
#include <cstring>
// Theme only the closed core's known HUD cards, and only while DrawHud is on
// the stack. Menu windows, the game HUD and other ImGui windows are untouched.
namespace hud_theme {
inline bool card(const char* name) {
 if (!name) return false;
 // Notification IDs are generated by the core; accept digits only and only
 // when called in the scoped NotificationQueue::Draw hook.
 constexpr const char prefix[]="##notification_";
 if (std::strncmp(name,prefix,sizeof(prefix)-1)==0) {
  const char* p=name+sizeof(prefix)-1; if (!*p) return false;
  for (;*p;++p) if (*p<'0' || *p>'9') return false;
  return true;
 }
 constexpr const char* names[]={"##hud_fps","##hud_cps","##hud_clock","##hud_cpu","##hud_ram",
  "##hud_resolution","##hud_watermark","##hud_info","##hud_active","##hud_hotkeys",
  "##hud_coordinates","##hud_keystrokes"};
 for (const auto* n:names) if (std::strcmp(name,n)==0) return true;
 return false;
}
inline float alpha(float v) { return std::isfinite(v) ? std::clamp(v,0.f,1.f) : .72f; }
struct Rgba { float r,g,b,a; };
inline Rgba background(float opacity) { return {.025f,.045f,.038f,alpha(opacity)}; }
inline Rgba border(float opacity) { return {.28f,.68f,.41f,alpha(opacity)*.46f}; }
}
